18:.timeline-scroll { overflow-x:auto; }.timeline-grid { min-width:800px; padding:0 17px 16px; display:grid; grid-template-columns:166px repeat(12,minmax(45px,1fr)); }.time-corner { height:41px; border-bottom:1px solid var(--line); }.time-label { height:41px; display:flex; align-items:center; justify-content:flex-start; border-bottom:1px solid var(--line); color:#a0a9b9; font:9px 'DM Mono',monospace; }.grid-row { display:contents; }.city-label-cell { height:60px; display:flex; align-items:center; gap:9px; border-bottom:1px solid #f0f2f6; }.city-label-cell>div { min-width:0; }.city-label-cell strong { display:block; color:#2a374c; font-size:11px; }.city-label-cell span { display:block; color:#97a2b4; margin-top:4px; font:9px 'DM Mono',monospace; }.city-avatar { width:27px; height:27px; border-radius:8px; display:grid; place-items:center; color:#29435e; font-size:9px; font-weight:800; }.avatar-london { background:#d0e0fa; }.avatar-newyork { background:#f6d7c5; }.avatar-sf { background:#d4eedc; }.avatar-tokyo { background:#e8dbf7; }.grid-track { height:60px; position:relative; border-bottom:1px solid #f0f2f6; border-left:1px solid #f1f3f7; }.grid-track::after { content:''; position:absolute; left:50%; top:0; bottom:0; border-left:1px dashed #f0f2f6; }.work-block { position:absolute; height:28px; top:16px; border-radius:7px; display:flex; align-items:center; padding:0 9px; color:#34516f; background:#d8e5f8; font-size:9px; font-weight:700; white-space:nowrap; overflow:hidden; }.work-block.london { background:#cfe1fb; }.work-block.newyork { background:#f6ddca; color:#744d36; }.work-block.sf { background:#d3efdc; color:#376248; }.work-block.tokyo { background:#e6dcf8; color:#5b4c7e; }.block-label { overflow:hidden; text-overflow:ellipsis; }.overlap-block { position:absolute; z-index:2; height:34px; top:13px; border-radius:8px; background:#a6e7bf; border:2px solid rgba(62,155,94,.22); color:#236442; display:flex; align-items:center; justify-content:center; font:9px 'DM Mono',monospace; font-weight:500; box-shadow:0 3px 9px rgba(77,185,120,.13); }.current-line { position:absolute; z-index:4; top:0; bottom:-2px; border-left:1px solid #e79c68; pointer-events:none; }.current-line::before { content:''; width:6px; height:6px; position:absolute; top:-3px; left:-3px; background:#e79c68; border-radius:50%; }.current-line span { position:absolute; top:-26px; left:5px; color:#c87748; font:9px 'DM Mono',monospace; white-space:nowrap; }.overlap-label { height:31px; display:flex; align-items:center; color:#8b98aa; font:9px 'DM Mono',monospace; }.overlap-label strong { color:#529e70; font-weight:500; }
